{"cards": [{"node_code": "N_ee38c49a3d0b7b02", "definition": "指脑血管病中需要外科干预的病理状态，涵盖脑动脉瘤、脑动静脉畸形、硬脑膜动静脉瘘等血管病变的外科治疗策略、手术技术及围手术期管理。", "boundary": "本节点聚焦于脑血管病变的外科处理。包括开颅夹闭、介入栓塞、血管重建等手术方式。不涵盖以内科药物（如抗血小板、降压）为主的缺血性卒中管理，除非涉及血管内介入治疗。与“脑血管外科”节点存在高度重叠，若“脑血管外科”侧重技术原理，本节点侧重疾病实体。", "includes": ["脑动脉瘤的外科夹闭与介入治疗", "脑动静脉畸形（AVM）的手术切除与栓塞", "硬脑膜动静脉瘘的外科干预"], "excludes": ["单纯内科药物治疗的缺血性脑卒中", "非血管性脑血管病（如脑炎、脱髓鞘）"], "sibling_distinctions": [{"other_code": "N_3636f1724bcf9578", "rule": "本节点与“脑血管外科”内容高度重合。若“脑血管外科”侧重手术技术、器械及解剖学基础，本节点侧重具体疾病（如动脉瘤、AVM）的临床诊疗路径。实际归类时，具体疾病案例优先归本节点，纯技术讨论归脑血管外科。"}, {"other_code": "N_41ca50de0f01633f", "rule": "本节点处理血管结构异常（如动脉瘤破裂），颅内血肿处理出血后果（如硬膜外血肿）。若动脉瘤破裂导致血肿，手术夹闭归本节点，清除血肿归颅内血肿，通常联合手术，主挂载视主要病理决定。"}], "cross_boundary_rule": "涉及血管内介入治疗时，若侧重神经介入技术归脑血管外科，若侧重特定疾病（如动脉瘤）的诊疗归本节点。"}, {"node_code": "N_41ca50de0f01633f", "definition": "指颅腔内异常积血形成的占位性病变，涵盖硬膜外、硬膜下及脑内血肿的病因、临床表现、影像学诊断、手术清除及术后管理。", "boundary": "本节点聚焦于血肿这一病理实体的外科处理。包括急性、亚急性及慢性血肿的鉴别与手术指征。不涵盖导致血肿的原发血管病变（如动脉瘤）的夹闭手术，除非作为血肿清除的联合步骤。", "includes": ["硬膜外血肿的手术清除与止血", "硬膜下血肿（急性/慢性）的外科引流", "脑内血肿的微创或开颅清除"], "excludes": ["非外伤性自发性脑出血的内科保守治疗", "血管畸形本身的修复手术（归脑血管病/外科）"], "sibling_distinctions": [{"other_code": "N_621945ba019c6549", "rule": "颅脑损伤是病因或临床综合征，颅内血肿是具体的病理改变。创伤性脑损伤的整体评估归颅脑损伤，若重点在于血肿的手术清除，归颅内血肿。"}, {"other_code": "N_ee38c49a3d0b7b02", "rule": "颅内血肿关注出血后的占位效应及清除，脑血管病关注血管结构异常（如动脉瘤）的修复。若因动脉瘤破裂出血，夹闭动脉瘤归脑血管病，清除血肿归颅内血肿。"}], "cross_boundary_rule": "外伤性血肿若伴随颅骨骨折，骨折处理归颅脑损伤或骨科，血肿清除归本节点。"}, {"node_code": "N_621945ba019c6549", "definition": "指由外力作用于头部导致的颅脑结构损伤，涵盖脑震荡、脑挫裂伤、颅骨骨折及弥漫性轴索损伤的急救、手术减压及康复管理。", "boundary": "本节点聚焦于创伤性颅脑损伤（TBI）的外科处理。包括急诊手术指征、去骨瓣减压、骨折复位及创伤后并发症管理。不涵盖非创伤性颅内病变（如肿瘤、血管畸形）的手术。", "includes": ["重型颅脑损伤的急诊手术与ICU管理", "开放性颅脑损伤的清创与修复", "颅骨骨折的手术复位与固定"], "excludes": ["非外伤性颅内血肿（如自发性脑出血）", "颅脑肿瘤或血管畸形的手术治疗"], "sibling_distinctions": [{"other_code": "N_41ca50de0f01633f", "rule": "颅脑损伤是创伤性病因，颅内血肿是病理结果。创伤性血肿的清除归颅内血肿，但创伤的整体评估、脑挫裂伤处理及颅骨骨折归颅脑损伤。"}, {"other_code": "N_fef1b736059a03f4", "rule": "颅脑损伤由外力引起，脑肿瘤为占位性病变。两者手术目的不同，前者为减压/清创，后者为切除肿瘤。"}], "cross_boundary_rule": "创伤性脑损伤若合并血管损伤（如外伤性动脉瘤），血管修复归脑血管病，脑组织损伤处理归颅脑损伤。"}]}
